r-color:var(--accent)}.btn.danger{color:var(--bad)}.asset-list{display:grid;gap:7px;max-height:72vh;overflow:auto}.asset{width:100%;text-align:left;border:1px solid var(--line);background:#fff;border-radius:10px;padding:10px;cursor:pointer}.asset.active{border-color:var(--accent);box-shadow:0 0 0 2px rgba(217,74,43,.12)}.asset strong{display:block}.asset small{display:block;color:var(--muted);margin-top:3px}.status{display:inline-block;margin-top:5px;padding:3px 6px;border-radius:999px;font-size:9px;font-weight:800;background:#eef0f2}.status.out_of_service{background:#fff0ef;color:var(--bad)}.status.maintenance{background:#fff6dd;color:var(--warn)}.section-title{margin:16px 0 8px;padding-top:14px;border-top:1px solid #eceff1;font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#525960}.contact-row,.event-row{padding:9px 0;border-bottom:1px solid #eceff1;font-size:12px}.contact-row:last-child,.event-row:last-child{border-bottom:0}.brain{background:linear-gradient(145deg,#fff,#fff7f4);border-color:#efc5b8}.brain-output{white-space:pre-wrap;max-height:350px;overflow:auto;margin-top:10px;padding:10px;border-radius:10px;background:#f7f7f5;font-size:12px;line-height:1.5}.quick{display:flex;flex-wrap:wrap;gap:6px}.quick button{border:1px solid #ead2ca;border-radius:999px;background:#fff;padding:6px 8px;font-size:10px;cursor:pointer}.due-list{display:grid;gap:7px}.due{padding:8px;border:1px solid #efdca9;border-radius:8px;background:#fffaf0;font-size:11px}.readonly{padding:8px 12px;background:#fff5d8;color:#6a5100;font-size:12px;margin-bottom:12px;border-radius:10px}.hidden{display:none!important}.tabs{display:flex;gap:6px;margin-bottom:10px}.tab{border:1px solid var(--line);background:#fff;padding:7px 9px;border-radius:8px;cursor:pointer}.tab.active{background:#17191c;color:#fff}.modal{position:fixed;inset:0;z-index:50;background:rgba(0,0,0,.45);display:none;place-items:center;padding:20px}.modal.open{display:grid}.modal-box{width:min(760px,100%);max-height:9