<script>
(()=>{'use strict';const CSRF=<?=json_encode($csrf,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR)?>,CAN_EDIT=<?=$canEdit?'true':'false'?>,CAN_SERVICE=<?=$canService?'true':'false'?>,CAN_CONTACTS=<?=$canContacts?'true':'false'?>,CAN_AGENT=<?=$canAgent?'true':'false'?>,$=id=>document.getElementById(id);let state={assets:[],contacts:[],events:[],summary:{},selected:null};
const fields=['name','assetType','purpose','brand','manufacturer','model','serialNumber','assetTag','manufactureYear','purchaseDate','installDate','expectedLifeYears','warrantyExpiresOn','purchasePrice','replacementCost','operationalStatus','conditionStatus','criticality','locationName','floorPlanId','floorPlanComponentId','widthInches','depthInches','heightInches','capacityText','utilityType','voltage','phase','amperage','btuRating','waterRequirement','drainRequirement','ventilationRequirement','maintenanceRequired','maintenanceIntervalDays','lastServiceOn','nextServiceOn','cleaningNotes','maintenanceNotes','operatingNotes','safetyNotes','partsConsumables','manualUrl','notes'];
async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Accept':'application/json'};if(opt.method&&opt.method!=='GET'){opt.headers['X-CSRF-Token']=CSRF;if(opt.body&&typeof opt.body!=='string'){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(opt.body)}}const r=await fetch(url,opt),d=await r.json().catch(()=>({ok:false,message:'Invalid server response'}));if(!r.ok||d.ok===false)throw new Error(d.message||`Request failed ${r.status}`);return d}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function updateStats(){const s=state.summary||{};$('sAssets').textContent=s.assets||0;$('sDue').textContent=s.dueWithin30Days||0;$('sOverdue').textContent=s.overdueMaintenance||0;$('sOut').textContent=s.outOfService||0;$('sCritical').textContent=s.criticalAssets||0;$('sContacts').textContent=s.serviceContacts||0}
function renderList(){const q=$('search').value.toLowerCase(),type=$('typeFilter').value,status=$('statusFilter').value;const rows=state.assets.filter(a=>(!q||[a.name,a.assetType,a.brand,a.manufacturer,a.model,a.serialNumber,a.assetTag,a.locationName,a.purpose].join(' ').toLowerCase().includes(q))&&(!type||a.assetType===type)&&(!status||a.operationalStatus===status));$('assetList').innerHTML=rows.length?rows.map(a=>`<button class="asset ${state.selected===a.id?'active':''}" data-id="${esc(a.id)}"><strong>${esc(a.name)}</strong><small>${esc(a.assetType)}${a.brand?' · '+esc(a.brand):''}${a.model?' · '+esc(a.model):''}</small><span class="status ${esc(a.operationalStatus)}">${esc(a.operationalStatus.replaceAll('_',' '))}</span></button>`).join(''):'<p class="muted">No matching equipment.</p>';document.querySelectorAll('.asset[data-id]').forEach(b=>b.onclick=()=>selectAsset(b.dataset.id))}
function renderContacts(){ $('contactList').innerHTML=state.contacts.length?state.contacts.map(c=>`<div class="contact-row"><strong>${esc(c.companyName)}</strong><div class="muted">${esc(c.specialty||'General equipment service')}${c.phone?' · '+esc(c.phone):''}${c.emergencyPhone?' · emergency '+esc(c.emergencyPhone):''}</div>${CAN_CONTACTS?`<button class="btn" data-contact="${esc(c.id)}" style="margin-top:5px">Edit</button>`:''}</div>`).join(''):'<p class="muted">No service contacts recorded.</p>';document.querySelectorAll('[data-contact]').forEach(b=>b.onclick=()=>openContact(state.contacts.find(c=>c.id===b.dataset.contact)));$('linkContactSelect').innerHTML='<option value="">Choose service contact…</option>'+state.contacts.map(c=>`<option value="${esc(c.id)}">${esc(c.companyName)}</option>`).join('')}
function renderDue(){const due=state.assets.filter(a=>a.maintenanceRequired&&a.nextServiceOn&&new Date(a.nextServiceOn)<=new Date(Date.now()+30*864e5)).sort((a,b)=>String(a.nextServiceOn).localeCompare(String(b.nextServiceOn)));$('dueList').innerHTML=due.length?due.map(a=>`<div class="due"><strong>${esc(a.name)}</strong><div>Due ${esc(a.nextServiceOn)} · ${esc(a.criticality)}</div></div>`).join(''):'<p class="muted">Nothing due within 30 days.</p>'}
function blank(){const a={id:'',name:'',assetType:'oven',purpose:'',brand:'',manufacturer:'',model:'',serialNumber:'',assetTag:'',manufactureYear:'',purchaseDate:'',installDate:'',expectedLifeYears:'',warrantyExpiresOn:'',purchasePrice:'',replacementCost:'',operationalStatus:'active',conditionStatus:'good',criticality:'medium',locationName:'',floorPlanId:'',floorPlanComponentId:'',widthInches:'',depthInches:'',heightInches:'',capacityText:'',utilityType:'',voltage:'',phase:'',amperage:'',btuRating:'',waterRequirement:'',drainRequirement:'',ventilationRequirement:'',maintenanceRequired:false,maintenanceIntervalDays:'',lastServiceOn:'',nextServiceOn:'',cleaningNotes:'',maintenanceNotes:'',operatingNotes:'',safetyNotes:'',partsConsumables:'',manualUrl:'',notes:'',contacts:[]};return a}
function selectAsset(id){state.selected=id;const a=state.assets.find(x=>x.id===id)||blank();$('assetId').value=a.id||'';fields.forEach(f=>{if(!$(f))return;let v=a[f]??'';if(f==='maintenanceRequired')v=a[f]?'1':'0';$(f).value=v});$('editorTitle').textContent=a.id?a.name:'New equipment';renderList();renderService(a)}
function renderService(a){$('linkedContacts').innerHTML=(a.contacts||[]).length?a.contacts.map(c=>`<div class="contact-row"><strong>${esc(c.companyName)}</strong><div class="muted">${esc(c.role)}${c.primary?' · primary':''}${c.phone?' · '+esc(c.phone):''}</div></div>`).join(''):'<p class="muted">No service contacts linked to this asset.</p>';const events=state.events.filter(e=>e.assetId===a.id);$('serviceHistory').innerHTML=events.length?events.map(e=>`<div class="event-row"><strong>${esc(e.servicedOn)} · ${esc(e.eventType)}</strong><div>${esc(e.description)}</div><div class="muted">${e.companyName?esc(e.companyName)+' · ':''}${e.technicianName?esc(e.technicianName)+' · ':''}${e.cost!=null?'$'+Number(e.cost).toFixed(2)+' · ':''}${e.nextDueOn?'next due '+esc(e.nextDueOn):''}</div></div>`).join(''):'<p class="muted">No service history recorded.</p>'}
function assetPayload(){const a={id:$('assetId').value};fields.forEach(f=>{if(!$(f))return;a[f]=$(f).value});a.maintenanceRequired=$('maintenanceRequired').value==='1';return a}
async function load(){try{const d=await api('api/equipment.php',{method:'GET'});state.assets=d.assets||[];state.contacts=d.contacts||[];state.events=d.events||[];state.summary=d.summary||{};updateStats();renderList();renderContacts();renderDue();if(state.selected&&state.assets.some(a=>a.id===state.selected))selectAsset(state.selected);else if(state.assets[0])selectAsset(state.assets[0].id);else selectAsset('')}catch(e){alert(e.message)}}
$('assetForm').onsubmit=async e=>{e.preventDefault();if(!CAN_EDIT)return;try{const d=await api('api/equipment.php',{method:'POST',body:{action:'save_asset',asset:assetPayload()}});state.assets=d.assets||[];state.summary=d.summary||state.summary;const saved=state.assets.find(a=>a.name===$('name').value&&(!state.selected||a.id===state.selected))||state.assets[0];state.selected=saved?.id||state.selected;updateStats();renderList();renderDue();selectAsset(state.selected);alert(d.message)}catch(e){alert(e.message)}};
$('newAsset')?.addEventListener('click',()=>{state.selected=null;selectAsset('');$('name').focus()});$('archiveAsset')?.addEventListener('click',async()=>{if(!state.selected||!confirm('Archive this equipment asset?'))return;try{await api('api/equipment.php',{method:'POST',body:{action:'archive_asset',id:state.selected}});state.selected=null;await load()}catch(e){alert(e.message)}});
$('search').oninput=renderList;$('typeFilter').onchange=renderList;$('statusFilter').onchange=renderList;document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));$('tabDetails').classList.toggle('hidden',b.dataset.tab!=='details');$('tabService').classList.toggle('hidden',b.dataset.tab!=='service')});
function openModal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').classList.add('open')}function closeModal(){$('modal').classList.remove('open')}$('modalClose').onclick=closeModal;$('modal').onclick=e=>{if(e.target===$('modal'))closeModal()};
function openContact(c={}){openModal(c.id?'Edit service contact':'Add service contact',`<form id="contactForm"><div class="two"><div class="field"><label>Company</label><input id="cCompany" required value="${esc(c.companyName||'')}"></div><div class="field"><label>Contact person</label><input id="cName" value="${esc(c.contactName||'')}"></div></div><div class="field"><label>Specialty</label><input id="cSpecialty" value="${esc(c.specialty||'')}" placeholder="Pizza ovens, refrigeration, gelato machines..."></div><div class="three"><div class="field"><label>Phone</label><input id="cPhone" value="${esc(c.phone||'')}"></div><div class="field"><label>Emergency phone</label><input id="cEmergency" value="${esc(c.emergencyPhone||'')}"></div><div class="field"><label>Email</label><input id="cEmail" value="${esc(c.email||'')}"></div></div><div class="field"><label>Website</label><input id="cWebsite" value="${esc(c.website||'')}"></div><div class="two"><div class="field"><label>Account #</label><input id="cAccount" value="${esc(c.accountNumber||'')}"></div><div class="field"><label>Contract #</label><input id="cContract" value="${esc(c.contractNumber||'')}"></div></div><div class="two"><label><input id="cPreferred" type="checkbox" ${c.preferred?'checked':''}> Preferred vendor</label><label><input id="cWarranty" type="checkbox" ${c.warrantyProvider?'checked':''}> Warranty provider</label></div><div class="field"><label>Notes</label><textarea id="cNotes">${esc(c.notes||'')}</textarea></div><button class="btn primary">Save contact</button></form>`);$('contactForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('api/equipment.php',{method:'POST',body:{action:'save_contact',contact:{id:c.id||'',companyName:$('cCompany').value,contactName:$('cName').value,specialty:$('cSpecialty').value,phone:$('cPhone').value,emergencyPhone:$('cEmergency').value,email:$('cEmail').value,website:$('cWebsite').value,accountNumber:$('cAccount').value,contractNumber:$('cContract').value,preferred:$('cPreferred').checked,warrantyProvider:$('cWarranty').checked,status:'active',notes:$('cNotes').value}}});state.contacts=d.contacts||[];renderContacts();closeModal()}catch(err){alert(err.message)}}}
$('newContact')?.addEventListener('click',()=>openContact());$('linkContactBtn')?.addEventListener('click',async()=>{if(!state.selected||!$('linkContactSelect').value)return alert('Choose an equipment asset and service contact.');try{const d=await api('api/equipment.php',{method:'POST',body:{action:'link_contact',assetId:state.selected,contactId:$('linkContactSelect').value,role:$('linkRole').value,primary:true}});state.assets=d.assets||state.assets;selectAsset(state.selected)}catch(e){alert(e.message)}});
$('addServiceEvent')?.addEventListener('click',()=>{if(!state.selected)return alert('Select equipment first.');openModal('Record service event',`<form id="eventForm"><div class="three"><div class="field"><label>Type</label><select id="eType"><option>maintenance</option><option>repair</option><option>inspection</option><option>cleaning</option><option>warranty</option><option>installation</option></select></div><div class="field"><label>Service date</label><input id="eDate" type="date" required value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Next due</label><input id="eNext" type="date"></div></div><div class="two"><div class="field"><label>Service company</label><select id="eContact"><option value="">None / internal</option>${state.contacts.map(c=>`<option value="${esc(c.id)}">${esc(c.companyName)}</option>`).join('')}</select></div><div class="field"><label>Technician</label><input id="eTech"></div></div><div class="field"><label>Work performed</label><textarea id="eDesc" required></textarea></div><div class="field"><label>Parts used</label><textarea id="eParts"></textarea></div><div class="two"><div class="field"><label>Cost</label><input id="eCost" type="number" step=".01"></div><div class="field"><label>Downtime minutes</label><input id="eDown" type="number"></div></div><button class="btn primary">Save service record</button></form>`);$('eventForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('api/equipment.php',{method:'POST',body:{action:'save_event',event:{assetId:state.selected,contactId:$('eContact').value,eventType:$('eType').value,status:'completed',servicedOn:$('eDate').value,nextDueOn:$('eNext').value,technicianName:$('eTech').value,description:$('eDesc').value,partsUsed:$('eParts').value,cost:$('eCost').value,downtimeMinutes:$('eDown').value}}});state.assets=d.assets||state.assets;state.events=[...(d.events||[]),...state.events.filter(x=>x.assetId!==state.selected)];state.summary=d.summary||state.summary;updateStats();renderDue();selectAsset(state.selected);closeModal()}catch(err){alert(err.message)}}});
async function ask(q){if(!CAN_AGENT)return;const msg=(q||$('brainInput').value).trim();if(!msg)return;$('brainOutput').textContent='Thinking from equipment records…';try{const d=await api('api/agent-brain.php',{method:'POST',body:{action:'ask',message:msg}});$('brainOutput').textContent=d.answer||'No answer.'}catch(e){$('brainOutput').textContent=e.message}}$('brainAsk')?.addEventListener('click',()=>ask());$('brainInput')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();ask()}});document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>ask(b.dataset.q));
load();})();
</script>
</body></html>